type Activity={id:string;type:'choice'|'input';prompt:string;options?:string[];answer:string|string[];explanation:string;hint:string;placeholder?:string};
type Diagram=
  |{type:'panel';kind:'route'|'addition'|'path'|'equation'|'angles'|'polygon'|'rectangle'|'checklist'|'final'}
  |{type:'composite-angle';variant:'summary'|'test-6'}
  |{type:'triangles';variant:'summary'|'test-7'};
type Stage={id:string;title:string;eyebrow:string;kind:'story'|'model'|'guided'|'practice'|'quiz'|'challenge'|'summary';body:string;note?:string;activity?:Activity;diagram?:Diagram;sourceItem?:number};
type Saved={version:1;stageIndex:number;responses:Record<string,string>;checked:Record<string,boolean>;results:Record<string,boolean>;attempts:Record<string,number>};
type StageJumpDetail={lessonNumber?:number;stageIndex?:number};

const KEY='mathnikita-lesson-52-progress-v1';
const normalized=(value:string)=>value.trim().toLocaleUpperCase('ru-RU').replace(/Ё/g,'Е').replace(/[−–—]/g,'-').replace(/[×·]/g,'X').replace(/\s+/g,'').replace(/(?:СМ|КМ|МИН|Ч|ГРАДУСА?|°|[.])$/,'');
const answerMatches=(response:string,answer:string|string[])=>{const variants=Array.isArray(answer)?answer:[answer];return variants.some(item=>normalized(response)===normalized(item))};

