function PanelDiagram({kind}:{kind:Extract<Diagram,{type:'panel'}>['kind']}){
  if(kind==='route')return <div className="chapter-two-review-panel" data-summary-topic-count="8"><div className="c2r-route">{['Сложение','Формулы','Уравнения','Углы','Многоугольники','Треугольники','Прямоугольники','Проверка'].map((item,index)=><span key={item}><b>{index+1}</b><strong>{item}</strong></span>)}</div></div>;
  if(kind==='addition')return <div className="chapter-two-review-panel" data-summary-topic="addition"><div className="c2r-formulas"><span><small>переместительное</small><b>a+b=b+a</b></span><span><small>сочетательное</small><b>(a+b)+c=a+(b+c)</b></span><span><small>удобная сумма</small><b>48+52=100</b></span></div></div>;
  if(kind==='path')return <div className="chapter-two-review-panel" data-summary-topic="formula"><div className="c2r-path"><b>s</b><span>путь</span><strong>=</strong><b>v</b><span>скорость</span><strong>·</strong><b>t</b><span>время</span></div></div>;
  if(kind==='equation')return <div className="chapter-two-review-panel" data-summary-topic="equation"><div className="c2r-equation"><span><b>1</b>выдели неизвестную часть</span><i>→</i><span><b>2</b>выполни обратное действие</span><i>→</i><span><b>3</b>проверь подстановкой</span></div></div>;
  if(kind==='angles')return <div className="chapter-two-review-panel" data-summary-topic="angles"><div className="c2r-angle-types"><span><i style={{transform:'rotate(-28deg)'}}/><b>&lt;90°</b><small>острый</small></span><span><i style={{transform:'rotate(-90deg)'}}/><b>90°</b><small>прямой</small></span><span><i style={{transform:'rotate(-132deg)'}}/><b>90°…180°</b><small>тупой</small></span><span><i style={{transform:'rotate(-180deg)'}}/><b>180°</b><small>развёрнутый</small></span></div></div>;
  if(kind==='polygon')return <div className="chapter-two-review-panel" data-summary-topic="polygon"><svg className="c2r-polygon" viewBox="0 0 620 250" role="img" aria-label="Пятиугольник: вершины, стороны, углы и периметр"><polygon points="105,205 60,92 190,35 320,92 275,205"/><circle cx="105" cy="205" r="6"/><circle cx="60" cy="92" r="6"/><circle cx="190" cy="35" r="6"/><circle cx="320" cy="92" r="6"/><circle cx="275" cy="205" r="6"/><text x="390" y="78">5 вершин</text><text x="390" y="125">5 сторон</text><text x="390" y="172">P = сумма сторон</text></svg></div>;
  if(kind==='rectangle')return <div className="chapter-two-review-panel" data-summary-topic="rectangle"><svg className="c2r-rectangle" viewBox="0 0 650 260" role="img" aria-label="Прямоугольник со сторонами a и b и формулой периметра"><rect x="65" y="45" width="300" height="165"/><path d="M65 65h20V45M345 45v20h20M365 190h-20v20M85 210v-20H65"/><text x="215" y="34">a</text><text x="45" y="132">b</text><text x="425" y="105">P=2a+2b</text><text x="425" y="155">P=2(a+b)</text></svg></div>;
  if(kind==='checklist')return <div className="chapter-two-review-panel"><div className="c2r-checklist">{['Условие','Тема','Правило','Вычисление','Единицы и ответ'].map((item,index)=><span key={item}><b>{index+1}</b>{item}</span>)}</div></div>;
  return <div className="chapter-two-review-panel"><div className="c2r-final"><b>12/12<br/><small>вопросов источника</small></b><b>23<br/><small>интерактивные проверки</small></b><b>20<br/><small>задач практики</small></b><b>№ 3<br/><small>готовность к контрольной</small></b></div></div>;
}

function CompositeAngleDiagram({variant}:{variant:Extract<Diagram,{type:'composite-angle'}>['variant']}){
  if(variant==='test-6')return <div className="chapter-two-review-diagram"><svg viewBox="0 0 720 330" role="img" aria-label="Вопрос 6: развёрнутый угол MKP, лучи KA и KB, угол MKB 115 градусов, угол AKP 94 градуса" data-source-test-figure="2-6" data-angle-mkb="115" data-angle-akp="94" data-result-angle-akb="29"><line x1="70" y1="255" x2="650" y2="255"/><line data-ray-angle="94" x1="360" y1="255" x2="345.35" y2="45.51"/><line data-ray-angle="65" x1="360" y1="255" x2="448.75" y2="64.67"/><path className="c2r-arc" d="M305 255A55 55 0 0 1 383.24 205.15"/><path className="c2r-arc is-result" d="M355.47 190.16A65 65 0 0 1 387.47 196.09"/><text x="52" y="278">M</text><text x="350" y="283">K</text><text x="660" y="278">P</text><text x="324" y="42">A</text><text x="458" y="64">B</text><text x="205" y="220">115°</text><text x="384" y="130">94°</text><text className="c2r-result-text" x="397" y="218">29°</text></svg></div>;
  return <div className="chapter-two-review-diagram"><svg viewBox="0 0 720 300" role="img" aria-label="Развёрнутый угол разделён лучом на углы 112 и 68 градусов" data-whole-angle="180" data-known-angle="112" data-missing-angle="68"><line x1="70" y1="235" x2="650" y2="235"/><line data-ray-angle="68" x1="360" y1="235" x2="434.92" y2="49.56"/><path className="c2r-arc" d="M300 235A60 60 0 0 1 382.48 179.37"/><path className="c2r-arc is-result" d="M382.48 179.37A60 60 0 0 1 420 235"/><text x="240" y="190">112°</text><text className="c2r-result-text" x="425" y="205">68°</text><text x="325" y="280">112°+68°=180°</text></svg></div>;
}

function TrianglesDiagram({variant}:{variant:Extract<Diagram,{type:'triangles'}>['variant']}){
  if(variant==='test-7')return <div className="chapter-two-review-diagram"><svg viewBox="0 0 820 320" role="img" aria-label="Вопрос 7: три треугольника со сторонами 5, 8, 11; 4, 6, 6; 5, 12, 13 сантиметров" data-source-test-figure="2-7" data-triangle-sides="5|8|11;4|6|6;5|12|13" data-isosceles-perimeter="16"><g data-side-scale="20" transform="translate(10 15)"><polygon points="15,210 89.55,143.35 235,210"/><text x="43" y="166">5</text><text x="164" y="170">8</text><text x="112" y="237">11</text><text x="72" y="278">разносторонний</text></g><g className="is-answer" data-side-scale="30" transform="translate(285 15)"><polygon points="15,210 55,96.86 195,210"/><text x="18" y="145">4</text><text x="126" y="146">6</text><text x="96" y="237">6</text><text x="72" y="278">P=16 см</text></g><g data-side-scale="20" transform="translate(545 15)"><polygon points="15,210 15,110 255,210"/><text x="0" y="164">5</text><text x="126" y="237">12</text><text x="132" y="148">13</text><text x="76" y="278">разносторонний</text></g></svg></div>;
  return <div className="chapter-two-review-diagram"><svg viewBox="0 0 720 300" role="img" aria-label="Равнобедренный треугольник со сторонами 7, 7 и 10 сантиметров" data-triangle-sides="7|7|10" data-side-scale="38" data-side-type="isosceles"><polygon points="170,245 360,58.93 550,245"/><path className="c2r-tick" d="M255 150l18 15M447 165l18-15"/><text x="245" y="130">7 см</text><text x="460" y="130">7 см</text><text x="342" y="278">10 см</text><text x="52" y="75">по сторонам:</text><text x="52" y="108">равнобедренный</text></svg></div>;
}

function DiagramView({diagram}:{diagram:Diagram}){
  if(diagram.type==='composite-angle')return <CompositeAngleDiagram variant={diagram.variant}/>;
  if(diagram.type==='triangles')return <TrianglesDiagram variant={diagram.variant}/>;
  return <PanelDiagram kind={diagram.kind}/>;
}

function emptySaved():Saved{return{version:1,stageIndex:0,responses:{},checked:{},results:{},attempts:{}}}
function loadSaved():Saved{try{const raw=localStorage.getItem(KEY);if(!raw)return emptySaved();const parsed=JSON.parse(raw) as Partial<Saved>;return{version:1,stageIndex:Math.min(Math.max(Number(parsed.stageIndex)||0,0),lessonFiftyTwoStages.length-1),responses:parsed.responses??{},checked:parsed.checked??{},results:parsed.results??{},attempts:parsed.attempts??{}}}catch{return emptySaved()}}
function stopNarration(){window.dispatchEvent(new CustomEvent('mathnikita-stop-narration'));if('speechSynthesis'in window)window.speechSynthesis.cancel()}

export function ChapterTwoReviewPlayer(){
  const[saved,setSaved]=useState<Saved>(()=>loadSaved());const stage=lessonFiftyTwoStages[saved.stageIndex];const activity=stage.activity;const response=activity?saved.responses[activity.id]??'':'';const wasChecked=activity?Boolean(saved.checked[activity.id]):false;const isCorrect=activity?Boolean(saved.results[activity.id]):true;const attempts=activity?saved.attempts[activity.id]??0:0;const canContinue=!activity||isCorrect||attempts>=2;
  const progress=useMemo(()=>Math.round(((saved.stageIndex+1)/lessonFiftyTwoStages.length)*100),[saved.stageIndex]);
  useEffect(()=>{localStorage.setItem(KEY,JSON.stringify(saved))},[saved]);
  useEffect(()=>{const handler=(event:Event)=>{const detail=(event as CustomEvent<StageJumpDetail>).detail;if(detail?.lessonNumber!==52||typeof detail.stageIndex!=='number')return;const index=Math.min(Math.max(detail.stageIndex,0),lessonFiftyTwoStages.length-1);stopNarration();setSaved(previous=>({...previous,stageIndex:index}))};window.addEventListener('mathnikita-go-to-stage',handler);return()=>window.removeEventListener('mathnikita-go-to-stage',handler)},[]);
  function setResponse(value:string){if(!activity)return;setSaved(previous=>({...previous,responses:{...previous.responses,[activity.id]:value},checked:{...previous.checked,[activity.id]:false},results:{...previous.results,[activity.id]:false}}))}
  function check(){if(!activity||!response)return;const correct=answerMatches(response,activity.answer);setSaved(previous=>({...previous,checked:{...previous.checked,[activity.id]:true},results:{...previous.results,[activity.id]:correct},attempts:{...previous.attempts,[activity.id]:(previous.attempts[activity.id]??0)+(correct?0:1)}}))}
  function next(){if(!canContinue||saved.stageIndex>=lessonFiftyTwoStages.length-1)return;stopNarration();setSaved(previous=>({...previous,stageIndex:previous.stageIndex+1}))}
  function previous(){if(saved.stageIndex===0)return;stopNarration();setSaved(previous=>({...previous,stageIndex:previous.stageIndex-1}))}
  return <section className="lesson-player chapter-two-review-player" data-lesson-number="52" data-source-reference="Мерзляк · задание № 2 «Проверьте себя» · итоги главы 2 · с. 102–105" data-test-item-count="12"><article className={`interactive-stage ${stage.kind==='summary'?'stage-summary':''}`} data-stage-id={stage.id} data-source-test-item={stage.sourceItem??undefined}><div className="stage-copy"><span className="stage-eyebrow">{stage.eyebrow}</span><h2>{stage.title}</h2><p>{stage.body}</p>{stage.note?<p className="theory-note">{stage.note}</p>:null}</div>{stage.diagram?<DiagramView diagram={stage.diagram}/>:null}{activity?<div className="activity-area"><h3>{activity.prompt}</h3>{activity.type==='choice'?<div className="choice-grid">{activity.options?.map(option=><button key={option} type="button" className={response===option?'selected':''} onClick={()=>setResponse(option)}>{option}</button>)}</div>:<label className="inline-answer"><span>Ответ</span><input value={response} placeholder={activity.placeholder??'Введите ответ'} onChange={event=>setResponse(event.target.value)}/></label>}<button type="button" className="check-button" disabled={!response} onClick={check}>Проверить</button>{wasChecked?<div className={`instant-feedback ${isCorrect?'good':'bad'}`} data-explanation={activity.explanation}><strong>{isCorrect?'Верно':'Пока нет'}</strong><span>{isCorrect?activity.explanation:attempts>=2?`${activity.hint} Можно перейти дальше и вернуться к заданию позже.`:activity.hint}</span></div>:null}</div>:null}<div className="lesson-controls"><button type="button" onClick={previous} disabled={saved.stageIndex===0}>Назад</button><span className="stage-counter">Этап {saved.stageIndex+1} из {lessonFiftyTwoStages.length} · {progress}%</span><button type="button" className="primary" onClick={next} disabled={saved.stageIndex===lessonFiftyTwoStages.length-1||!canContinue}>{saved.stageIndex===lessonFiftyTwoStages.length-1?'Итог':'Дальше'}</button></div></article></section>;
}
